  "Record the EU regulation/table, CN code, origin and applicable year.":
    "請記錄歐盟法規／表格、CN 代碼、原產地與適用年度。",
  "The app has no official default-value table yet. Enter only the applicable published EU value; illustrative values are never inserted.":
    "本應用程式尚無官方預設值表。請僅輸入適用的已公布歐盟數值；系統絕不會插入示意數值。",
  "Open EU default-value regulation": "開啟歐盟預設值法規",
  "Direct emissions (tCO₂e/t)": "直接排放（tCO₂e/t）",
  "Indirect emissions (tCO₂e/t), if applicable": "間接排放（tCO₂e/t，如適用）",
  "Upload the producer's independent verification report. Then enter the report details below so its coverage can be checked.":
    "請上傳生產者的獨立查證報告，然後於下方輸入報告詳細資料，以便核對其涵蓋範圍。",
  "Producer verification report": "生產者查證報告",
  "A document is attached. Its contents and accreditation still require human review.":
    "已附加文件。其內容與認證仍需人工檢視。",
  "Report covers from": "報告涵蓋起始",
  "Report covers until": "報告涵蓋結束",
  "Select country": "選擇國家",
  "Passing these field checks does not replace an independent review of the report and accreditation.":
    "通過這些欄位檢查不能取代對報告與認證的獨立檢視。",
  "3. Tonnes actually used": "3. 實際使用噸數",
  "Enter material consumed by your process, including losses. A delivery receipt is not the same as use.":
    "請輸入流程耗用的物料（含損耗）。送貨收據不等於使用量。",
