  "Unsaved changes": "尚未儲存的變更",
  "Confirm remove source": "確認移除來源",
  "Remove source": "移除來源",
  "Usage is split by production process. Edit it on the Precursor sources tab.":
    "用量依生產流程分列。請於「前驅物來源」頁籤編輯。",
  "{source}: exact 8-digit precursor CN code":
    "{source}：正確的 8 位數前驅物 CN 代碼",
  "{source}: producer installation and country": "{source}：生產者設施與國家",
  " — enter the applicable official EU default and its source; illustrative comparison values are not used here.":
    " —— 請輸入適用的官方歐盟預設值及其來源；此處不使用示意比較數值。",
  "The report is attached. Enter its values manually; automatic suggestions require a text PDF.":
    "已附加報告。請手動輸入其數值；自動建議需要文字型 PDF。",
  "Check each value from the PDF before using it.":
    "使用前請逐一核對 PDF 中的各項數值。",
  "No unambiguous precursor values found. The report is attached; enter its values manually.":
    "找不到明確的前驅物數值。報告已附加；請手動輸入其數值。",
  "Could not read text from this PDF. The report is attached; enter its values manually.":
    "無法讀取此 PDF 的文字。報告已附加；請手動輸入其數值。",
  specificEmbeddedDirectTco2PerT: "specificEmbeddedDirectTco2PerT",
  specificEmbeddedIndirectTco2PerT: "specificEmbeddedIndirectTco2PerT",
  cnCode: "cnCode",
  reportingPeriodStart: "reportingPeriodStart",
  reportingPeriodEnd: "reportingPeriodEnd",
  "Use value": "使用此數值",
