    "此原產地適用歐盟附表中的「其他國家及地區」列。",
  "EU value selected": "已選擇歐盟數值",
  "Select this EU value": "選擇此歐盟數值",
  "The number comes from the Commission's corrected August 2026 schedule. Check the legal text before filing.":
    "此數字來自執委會更正後的 2026 年 8 月附表。申報前請核對法規條文。",
  Regulation: "法規",
  "Commission workbook": "執委會工作表",
  "Choose the exact 8-digit CN code and production country to find a published EU default. If no unique row exists, obtain the producer's report.":
    "請選擇正確的 8 位數 CN 代碼與生產國家，以查找已公布的歐盟預設值。若無唯一對應列，請取得生產者報告。",
  "An EU default schedule for this reporting year is not loaded. Obtain the producer's report.":
    "尚未載入此申報年度的歐盟預設值附表。請取得生產者報告。",
