  "Aluminium foil (≤ 0.2 mm)": "鋁箔（≤ 0.2 mm）",
  "Aluminium tubes and pipes": "鋁管",
  "Aluminium tube or pipe fittings": "鋁管件",
  "Aluminium structures and parts": "鋁結構體及組件",
  "Aluminium reservoirs and tanks (> 300 l)": "鋁貯槽及儲槽（> 300 公升）",
  "Aluminium casks, drums, cans (≤ 300 l)": "鋁桶、鼓、罐（≤ 300 公升）",
  "Aluminium containers for gas": "鋁製氣體容器",
  "Aluminium stranded wire and cables": "鋁絞線及電纜",
