    "直接投入本產品的商品。請從 CBAM 目錄選取，以確保 CN 代碼正確。",
  "Where it was made, and which value you want to use for it.":
    "其生產地，以及您要採用的數值。",
  "Where this precursor was produced.": "此前驅物的生產地。",
  "Not identified": "未確定",
  "The country of production cannot be identified": "無法確定生產國",
  "The highest default value for the CN code applies — Annex IV to Implementing Regulation 2025/2621. An actual value needs a country of origin.":
    "適用該 CN 代碼的最高預設值（施行條例 2025/2621 附件 IV）。實際值需要原產國。",
  "Which value do you want to use?": "您要使用哪一種數值？",
  "The EU's figure. Nothing to ask anyone.": "歐盟數值。無需向任何人詢問。",
