  "{left} of {total} still unticked. Anything left unticked is a question a verifier will have to ask.":
    "仍有 {left}／{total} 項未勾選。未勾選的項目即為查證機構必須提問的問題。",
  "What to attach here": "此處應附加的內容",
  "What to attach": "應附加的內容",
  "“Factory-licence-TH-RAYONG-01.pdf” for identity; “FT-2201-calibration-2026-03-12.pdf” for the gas meter named in section 4.":
    "「Factory-licence-TH-RAYONG-01.pdf」作為身分證明；「FT-2201-calibration-2026-03-12.pdf」對應第 4 節所列的天然氣表。",
  "Copy setup from previous month": "複製上個月的設定",
