  "This precursor has no workspace of its own yet. Track a report for it and its own months, readiness and settings open here.":
    "此前驅物尚無自身的工作區。為其追蹤報告後，其自身的月份、就緒狀態與設定即可於此開啟。",
  "Not sent": "未寄送",
