  supplier: "供應商",
  "tier deep": "層深度",
  "tiers deep": "層深度",
  "submitted earlier": "先前已提交",
  "not started (critical)": "未開始（關鍵）",
  "No Smart Link goes out for these — {supplier} is you. Report the embedded emissions of your own installation the same way an external supplier would, and the declaration treats it identically: same {regulation} checklist, same AI check, same verification trail.":
    "這些項目不會寄出智慧連結——{supplier} 即為您本人。請以外部供應商相同的方式申報自有設施的隱含排放，申報將以完全相同的方式處理：相同的 {regulation} 檢查表、相同的 AI 檢查，以及相同的查證軌跡。",
  "You’re {supplier}. To keep shipping {origin} {sector} into the {destination}, {exporter} has to report the embedded emissions of the goods they buy from you — under {regulation}. This takes about 10 minutes, it’s free, and you don’t need an account.":
    "您是 {supplier}。為了讓 {origin} {sector} 的產品持續出口至 {destination}，{exporter} 必須依 {regulation} 申報其向您購買之產品的隱含排放。此作業約需 10 分鐘，免費，且無需帳號。",
  "Your figures are checked automatically before you submit and land in your own supplier record, so the next declaration starts pre-filled instead of blank. Colleagues can be assigned the sections that belong to their department.":
    "您的數字於提交前會自動檢查，並保存於您自身的供應商紀錄中，因此下次申報將預先填入，而非從空白開始。可將屬於其部門的章節指派給同事。",
  "Your figures are checked automatically before you submit, encrypted, and shared only with {exporter} for this declaration. You can invite colleagues to fill the parts that belong to their department.":
    "您的數字於提交前會自動檢查並加密，且僅會為此申報與 {exporter} 共用。您可以邀請同事填寫屬於其部門的部分。",
  "Reporting as": "申報身分",
  "Requested by": "索取者",
  "Goods in scope": "範圍內產品",
  "Documents requested": "索取的文件",
  "{total} ({required} required)": "{total}（必要 {required}）",
  "One request for the period": "期間內一次請求",
  "One request per month": "每月一次請求",
  "Works / alloy test certificate (EN 10204 3.1)":
    "工廠／合金試驗證明（EN 10204 3.1）",
  "Mill Test Certificate (EN 10204 3.1)": "材料試驗證明（EN 10204 3.1）",
  "CBAM communication / embedded-emissions sheet": "CBAM 通訊／隱含排放表",
  "Certificate of Origin (COO)": "原產地證明（COO）",
  "Verification statement (accredited verifier)": "查證聲明（認可查證機構）",
  "Please report at installation level using actual data where you have it. If you only have default factors, mark the method as “default”. Reach out if anything is unclear — we'd rather help than receive a guess.":
    "請以設施層級申報，並於有實際數據時使用實際數據。若僅有預設係數，請將方法標記為「預設值」。如有任何不清楚之處，請與我們聯繫——我們寧可協助您，也不願收到猜測的數字。",
  "Who produced the goods and where.": "誰製造此產品，以及於何處製造。",
  "Route and quantity per good.": "各產品的路線與數量。",
  "Direct & indirect emissions per tonne.": "每公噸直接與間接排放。",
  "Fuel, power and materials the figure is derived from.":
    "此數字所依據的燃料、電力與材料。",
  "Power use & grid factor (electrolysis goods).":
    "電力用量與電網係數（電解產品）。",
  "Embedded emissions carried in from inputs.": "由投入物帶入的隱含排放。",
  "Any carbon price paid in country of origin.": "於原產國所繳納的任何碳價。",
  "Accredited verifier and outcome.": "認可查證機構及結果。",
  "Certificates and supporting files.": "證明文件與佐證檔案。",
  "Zinc coating": "鍍鋅",
